+// ---- dom identity ----------------------------------------------------------
+// These steps record the live <li> nodes a scenario holds across an interaction and
+// later assert those exact nodes are still attached, proving the app mutated the list
+// in place rather than re-rendering it.
+
+function recordedItems() {
+  const items = this._recordedItems;
+  assert(Array.isArray(items), 'no recorded todo-list item elements — call "the user records the current todo-list item elements" first');
+  return items;
+}
+
+When('the user records the current todo-list item elements', function () {
+  this._recordedItems = Array.from(this.document.querySelectorAll('.todo-list li'));
+});
+
+Then('the recorded todo-list item elements are still attached to the document', function () {
+  const items = recordedItems.call(this);
+  assert(items.length > 0, 'expected at least one recorded todo-list item element');
+  items.forEach((el, i) => {
+    assert.strictEqual(el.isConnected, true, `recorded todo-list item element at index ${i + 1} is no longer attached to the document`);
+  });
+});
+
+Then('the first recorded todo-list item element has class {string}', function (cls) {
+  assert(recordedItems.call(this)[0].classList.contains(cls), `expected first recorded todo-list item element to have class "${cls}"`);
+});
+
+Then('the first recorded todo-list item element does not have class {string}', function (cls) {
+  assert(!recordedItems.call(this)[0].classList.contains(cls), `expected first recorded todo-list item element not to have class "${cls}"`);
+});
+
+Then('every recorded todo-list item element has class {string}', function (cls) {
+  const items = recordedItems.call(this);
+  assert(items.length > 0, 'expected at least one recorded todo-list item element');
+  const all = items.every((li) => li.classList.contains(cls));
+  assert(all, `expected every recorded todo-list item element to have class "${cls}"`);
+});
+
+Then('no recorded todo-list item element has class {string}', function (cls) {
+  const items = recordedItems.call(this);
+  const withClass = items.filter((li) => li.classList.contains(cls));
+  assert.strictEqual(withClass.length, 0, `expected no recorded todo-list item element to have class "${cls}", found ${withClass.length}`);
+});
+
+Then('the recorded todo-list item element at index {int} is still attached to the document', function (index) {
+  const items = recordedItems.call(this);
+  const el = items[index - 1];
+  assert(el, `expected a recorded todo-list item element at index ${index}`);
+  assert.strictEqual(el.isConnected, true, `recorded todo-list item element at index ${index} is no longer attached to the document`);
+});
